/**
 * Phase B review round, F1: a read log never costs a family. Every admission, OVERSIZED, NO_ROOM and eviction decision
 * is made on a family's bytes without its log, exactly as with the read-log switch off; logs occupy only the slack and
 * are dropped, coldest family first, whenever a charge needs it, and first when a family sheds; a log that does not fit
 * after its family was admitted is not kept. Charged bytes equal a recomputation after every drop.
 */
@Timeout(120)
class LmdbPlanCacheRevalidationSlackTest {

	private static final int FAMILIES = 32;
	/** Learned keys a planning reads for a log larger than the difference between a flight and its family. */
	private static final int LARGE_LOG_READS = 32;
	/** Learned keys a planning reads for a log between the difference of a flight and its family, and the flight. */
	private static final int MEDIUM_LOG_READS = 8;

	@TempDir
	Path directory;
	private String previousSwitch;
	private LmdbOperatorFeedbackStats stats;
	private int requests;

	@BeforeEach
	void rememberSwitch() {
		previousSwitch = System.getProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY);
	}

	@AfterEach
	void restoreSwitch() {
		if (previousSwitch == null) {
			System.clearProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY);
		} else {
			System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, previousSwitch);
		}
	}

	@Test
	void underPressureTheSwitchOnCacheHoldsAndEvictsExactlyAsTheSwitchOffCache() throws Exception {
		Sizes sizes = sizes();
		// Room for three families without their logs, plus a little less than one log of slack.
		long budget = LmdbPlanDecisionCache.doorkeeperBytes(FAMILIES) + 3L * sizes.core() + sizes.log() / 2L;
		Run off = run(false, budget);
		Run on = run(true, budget);

		assertAll(
				() -> assertTrue(off.evictions() > 0L, "COVERAGE_PREREQUISITE: the run evicts: " + off),
				() -> assertEquals(off.families(), on.families(), "families: off=" + off + " on=" + on),
				() -> assertEquals(off.hits(), on.hits(), "hits: off=" + off + " on=" + on),
				() -> assertEquals(off.publications(), on.publications(), "publications: off=" + off + " on=" + on),
				() -> assertEquals(off.evictions(), on.evictions(), "evictions: off=" + off + " on=" + on),
				() -> assertEquals(off.outcomes(), on.outcomes(), "every request's outcome"),
				() -> assertTrue(on.recomputationsMatched(), "charged bytes equal a recomputation after every step"),
				() -> assertTrue(on.droppedLogs() > 0L, "COVERAGE_PREREQUISITE: logs were dropped: " + on));
	}

	@Test
	void underPressureRefreshesWhoseCommitAdmitsAnotherKeyDecideExactlyAsTheSwitchOffCache() throws Exception {
		long[] ranked = rankedSizes();
		long core = ranked[0];
		long log = ranked[1];
		long pendingInCommit = ranked[2];
		long refreshedCore = ranked[3];
		// Room for a refreshed and a built ranked family without their logs, the reservations held while another key's
		// flight plans inside a refresh's commit window, and half a log: the built family's log survives the first
		// refresh; when the built family refreshes, the flight admitted inside its commit window needs its log's slack.
		long budget = LmdbPlanDecisionCache.doorkeeperBytes(FAMILIES) + refreshedCore + core + pendingInCommit
				+ log / 2L;
		RefreshRun off = runWithRefreshes(false, budget);
		RefreshRun on = runWithRefreshes(true, budget);

		assertAll(
				() -> assertTrue(off.evictions() > 0L, "COVERAGE_PREREQUISITE: the run evicts: " + off),
				() -> assertTrue(off.outcomes().stream().anyMatch(outcome -> outcome.contains("refreshed-physical")),
						"COVERAGE_PREREQUISITE: refreshes publish with the switch off: " + off.outcomes()),
				() -> assertTrue(on.refreshingLogsDroppedInCommit() > 0L,
						"COVERAGE_PREREQUISITE: an admission inside a commit window dropped the refreshing family's log: "
								+ on),
				() -> assertEquals(off.outcomes(), on.outcomes(), "every request's and refresh's outcome"),
				() -> assertEquals(off.families(), on.families(), "families: off=" + off + " on=" + on),
				() -> assertEquals(off.hits(), on.hits(), "hits: off=" + off + " on=" + on),
				() -> assertEquals(off.publications(), on.publications(), "publications: off=" + off + " on=" + on),
				() -> assertEquals(off.evictions(), on.evictions(), "evictions: off=" + off + " on=" + on),
				() -> assertTrue(on.recomputationsMatched(), "charged bytes equal a recomputation after every step"));
	}

	/**
	 * Six ranked keys, each built (or hit) and then requested after a Frontier drift, which serves it stale and submits
	 * its refresh; inside every refresh publication's commit window the next key is requested (a hit, or a flight whose
	 * admission and publication need the slack the logs occupy). Each step waits for its refresh.
	 */
	private RefreshRun runWithRefreshes(boolean validation, long budget) throws Exception {
		System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, Boolean.toString(validation));
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILIES, 1, budget);
		try {
			LmdbPlanDecisionCache decisions = cache.decisionCacheForTest();
			List<String> outcomes = new ArrayList<>();
			boolean matched = true;
			long[] refreshingLogsDropped = { 0L };
			for (int round = 0; round < 3; round++) {
				for (int key = 0; key < 6; key++) {
					int next = (key + 1) % 6;
					int refreshing = key;
					outcomes.add("build-or-hit " + key + "=" + rankedRequest(cache, key,
							LmdbPlanCacheRevalidationTest.learned(17L, 3L)));
					AtomicBoolean once = new AtomicBoolean();
					List<String> duringCommit = new ArrayList<>();
					decisions.setBeforeRefreshCommitForTest(() -> {
						if (once.compareAndSet(false, true)) {
							boolean logBefore = keepsLog(cache, refreshing);
							duringCommit.add("in-commit " + next + "=" + rankedRequest(cache, next,
									LmdbPlanCacheRevalidationTest.learned(17L, 3L)));
							if (logBefore && !keepsLog(cache, refreshing)) {
								refreshingLogsDropped[0]++;
							}
						}
					});
					outcomes.add("drift " + key + "=" + rankedRequest(cache, key,
							LmdbPlanCacheRevalidationTest.learned(17L, 20L + round, 3L, 7L, 0L, true)));
					LmdbPlanCacheRevalidationLogDropTest.awaitRefreshesIdle(cache);
					decisions.setBeforeRefreshCommitForTest(null);
					outcomes.addAll(duringCommit);
					outcomes.add("champion " + key + "=" + champion(cache, key));
					matched &= LmdbPlanCacheRevalidationTest.recomputedCharges(decisions) == cache.retainedBytes();
					matched &= cache.retainedBytes() <= budget;
				}
			}
			LmdbPlanDecisionCache.Statistics statistics = decisions.statistics();
			long dropped = statistics.revalidation().logsDropped().values().stream().mapToLong(Long::longValue).sum();
			return new RefreshRun(statistics.families(), statistics.hits(), statistics.publications(),
					statistics.evictions(), outcomes, matched, dropped, statistics.stalePublications(),
					refreshingLogsDropped[0]);
		} finally {
			cache.close();
		}
	}

	/**
	 * A ranked family's bytes without its log, its log's charge, the reservations held while another key's flight plans
	 * inside the family's refresh commit window, and the family's bytes once refreshed, measured on an unconstrained
	 * cache.
	 */
	private long[] rankedSizes() throws Exception {
		System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, "true");
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILIES, 1, 1L << 30);
		try {
			LmdbPlanDecisionCache decisions = cache.decisionCacheForTest();
			if (stats == null) {
				stats = LmdbPlanCacheRevalidationTest.feedback(directory);
			}
			assertFalse(rankedRequest(cache, 0, LmdbPlanCacheRevalidationTest.learned(17L, 3L)));
			LmdbPlanDecisionCache.FamilyVersion family = decisions.residentFamiliesForTest().values().iterator().next();
			long core = family.retainedBytes();
			long log = family.dispatcher().variants().get(0).readLogBasis().chargedBytes();
			long[] pending = new long[1];
			AtomicBoolean once = new AtomicBoolean();
			decisions.setBeforeRefreshCommitForTest(() -> {
				if (once.compareAndSet(false, true)) {
					QueryRoot source = LmdbPlanCacheRevalidationTest.query("_anon_s" + requests++, "urn:refresh:1");
					LmdbPipelinePlanCache.Context context = LmdbPlanCacheRevalidationTest.learned(17L, 3L);
					cache.getOrComputePlan(source, context, context::revision, () -> {
						pending[0] = decisions.reservedBytesForTest();
						return new LmdbPipelinePlanCache.PlanComputation(source,
								LmdbPlanCacheRevalidationTest.replayOnlySummary(), null);
					}, () -> Long.MIN_VALUE, null);
				}
			});
			assertTrue(rankedRequest(cache, 0, LmdbPlanCacheRevalidationTest.learned(17L, 20L, 3L, 7L, 0L, true)),
					"COVERAGE_PREREQUISITE: a drift serves the ranked family stale and refreshes it");
			LmdbPlanCacheRevalidationLogDropTest.awaitRefreshesIdle(cache);
			decisions.setBeforeRefreshCommitForTest(null);
			long refreshedCore = decisions.residentFamiliesForTest().values().iterator().next().retainedBytes();
			assertTrue(log > 0L && pending[0] > 0L && refreshedCore > core, "COVERAGE_PREREQUISITE: measured sizes");
			return new long[] { core, log, pending[0], refreshedCore };
		} finally {
			cache.close();
		}
	}

	record RefreshRun(long families, long hits, long publications, long evictions, List<String> outcomes,
			boolean recomputationsMatched, long droppedLogs, long stalePublications,
			long refreshingLogsDroppedInCommit) {
	}

	/** Whether the resident variant of {@code urn:refresh:key} keeps a read log (false when absent). */
	private static boolean keepsLog(LmdbPipelinePlanCache cache, int key) {
		for (LmdbPlanDecisionCache.FamilyVersion family : cache.decisionCacheForTest()
				.residentFamiliesForTest()
				.values()) {
			for (LmdbPlanDecisionCache.PlanVariant variant : family.dispatcher().variants()) {
				TupleExpr plan = variant.champion().materialize();
				TupleExpr arg = plan instanceof QueryRoot root ? root.getArg() : plan;
				if (arg instanceof Projection projection && projection.getArg() instanceof StatementPattern pattern
						&& ("urn:refresh:" + key).equals(pattern.getPredicateVar().getValue().stringValue())) {
					return variant.keepsReadLog();
				}
			}
		}
		return false;
	}

	/** A ranked request of key {@code key} (one learned read, detached refresh work); returns whether it hit. */
	private boolean rankedRequest(LmdbPipelinePlanCache cache, int key, LmdbPipelinePlanCache.Context context) {
		QueryRoot source = LmdbPlanCacheRevalidationTest.query("_anon_s" + requests++, "urn:refresh:" + key);
		return cache.getOrComputePlan(source, context, context::revision, () -> {
			LmdbPlanCacheRevalidationTest.logicalRead(stats, LmdbPlanCacheRevalidationTest.logical("slack-" + key));
			source.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
			return new LmdbPipelinePlanCache.PlanComputation(source, LmdbPlanCacheRevalidationTest.rankedSummary(),
					LmdbPlanCacheRevalidationLogDropTest.refreshWork(key));
		}, () -> Long.MIN_VALUE,
				new LmdbPlanCacheRevalidationTest.StubValidator(LmdbPlanningReadLog.Verdict.IDENTICAL)).cacheHit();
	}

	private final Set<String> taught = new HashSet<>();

	/** Gives the logical key exact evidence (once), so that a read of it keeps the key in a compact log too. */
	private void teachOnce(String name) {
		if (taught.add(name)) {
			LmdbPlanCacheRevalidationTest.teach(stats, LmdbPlanCacheRevalidationTest.logical(name), 40, 7L);
		}
	}

	/** The champion's physical fingerprint of the resident family of {@code urn:refresh:key}, or "absent". */
	private static String champion(LmdbPipelinePlanCache cache, int key) {
		for (LmdbPlanDecisionCache.FamilyVersion family : cache.decisionCacheForTest()
				.residentFamiliesForTest()
				.values()) {
			for (LmdbPlanDecisionCache.PlanVariant variant : family.dispatcher().variants()) {
				TupleExpr plan = variant.champion().materialize();
				TupleExpr arg = plan instanceof QueryRoot root ? root.getArg() : plan;
				if (arg instanceof Projection projection && projection.getArg() instanceof StatementPattern pattern
						&& ("urn:refresh:" + key).equals(pattern.getPredicateVar().getValue().stringValue())) {
					return variant.champion().physicalFingerprint() + "/rollbacks="
							+ variant.rollbackVersions().size() + "/" + family.semanticValidity();
				}
			}
		}
		return "absent";
	}

	@Test
	void aPublicationWhoseLogNeedsTheSlackDropsColderLogsFirst() throws Exception {
		Sizes sizes = sizes(LARGE_LOG_READS);
		assertTrue(sizes.reservation() < sizes.core() + sizes.log() - 8L && sizes.core() <= sizes.reservation(),
				"COVERAGE_PREREQUISITE: a flight fits next to one log and a second log needs the slack: " + sizes);
		// The second key's flight fits next to the first family and its log; after the publication, two families and
		// one log fit, but not two logs.
		long budget = LmdbPlanDecisionCache.doorkeeperBytes(FAMILIES) + sizes.core() + sizes.log()
				+ sizes.reservation() + 8L;
		System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, "true");
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILIES, 1, budget);
		try {
			request(cache, 0, LARGE_LOG_READS);
			assertNotNull(variant(cache, 0).readLogBasis().log(), "COVERAGE_PREREQUISITE: the first log fits");
			request(cache, 1, LARGE_LOG_READS);

			LmdbPlanCacheRevalidation.Snapshot counters = cache.decisionCacheForTest().statistics().revalidation();
			assertAll(
					() -> assertEquals(2, cache.entryCount(), "both families are published"),
					() -> assertNull(variant(cache, 0).readLogBasis().log(), "the colder log went first"),
					() -> assertEquals(LmdbPlanCacheRevalidation.DROPPED_FOR_SLACK,
							variant(cache, 0).readLogBasis().missingReason()),
					() -> assertNotNull(variant(cache, 1).readLogBasis().log(), "the newer family keeps its log"),
					() -> assertEquals(Map.of(LmdbPlanCacheRevalidation.DROPPED_FOR_SLACK, 1L),
							counters.logsDropped()),
					() -> assertEquals(LmdbPlanCacheRevalidationTest.recomputedCharges(cache.decisionCacheForTest()),
							cache.retainedBytes()),
					() -> assertTrue(cache.retainedBytes() <= budget));
		} finally {
			cache.close();
		}
	}

	@Test
	void aLogThatStillDoesNotFitIsNotKeptAndItsFamilyIsPublishedAnyway() throws Exception {
		Sizes sizes = sizes(LARGE_LOG_READS);
		assertTrue(sizes.reservation() + 8L < sizes.log(),
				"COVERAGE_PREREQUISITE: a log needs more than the slack a flight leaves: " + sizes);
		// Each key's flight just fits next to the families without their logs; no log fits after its publication.
		long budget = LmdbPlanDecisionCache.doorkeeperBytes(FAMILIES) + sizes.core() + sizes.reservation() + 8L;
		System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, "true");
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILIES, 1, budget);
		try {
			request(cache, 0, LARGE_LOG_READS);
			request(cache, 1, LARGE_LOG_READS);

			LmdbPlanCacheRevalidation.Snapshot counters = cache.decisionCacheForTest().statistics().revalidation();
			assertAll(
					() -> assertEquals(2, cache.entryCount(), "a log never refuses its family"),
					() -> assertNull(variant(cache, 0).readLogBasis().log()),
					() -> assertNull(variant(cache, 1).readLogBasis().log()),
					() -> assertEquals(LmdbPlanCacheRevalidation.NO_ROOM,
							variant(cache, 1).readLogBasis().missingReason()),
					() -> assertEquals(Map.of(LmdbPlanCacheRevalidation.NO_ROOM, 2L), counters.logsDropped()),
					() -> assertEquals(0L, counters.readLogBytes()),
					() -> assertEquals(LmdbPlanCacheRevalidationTest.recomputedCharges(cache.decisionCacheForTest()),
							cache.retainedBytes()),
					() -> assertTrue(cache.retainedBytes() <= budget));
		} finally {
			cache.close();
		}
	}

	@Test
	void aFlightsReservationTakesTheSlackOfTheColdestLogWhileItPlans() throws Exception {
		Sizes sizes = sizes();
		assertTrue(sizes.log() + 8L <= sizes.reservation() && sizes.core() + sizes.log() <= sizes.reservation() + 8L,
				"COVERAGE_PREREQUISITE: a family and its log fit where a flight did: " + sizes);
		// The second key's flight fits next to the first family, but not next to its log; after the publication, the
		// two families and the second one's log fit.
		long doorkeeper = LmdbPlanDecisionCache.doorkeeperBytes(FAMILIES);
		long budget = doorkeeper + sizes.core() + sizes.reservation() + 8L;
		System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, "true");
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILIES, 1, budget);
		try {
			request(cache, 0);
			assertNotNull(variant(cache, 0).readLogBasis().log(), "COVERAGE_PREREQUISITE: the first log fits");
			List<String> duringFlight = new ArrayList<>();
			request(cache, 1, 1, () -> {
				duringFlight.add(variant(cache, 0).readLogBasis().missingReason());
				long occupied = cache.retainedBytes() + cache.decisionCacheForTest().reservedBytesForTest()
						+ doorkeeper;
				duringFlight.add(occupied <= budget ? "within-budget" : "over-budget:" + occupied);
			});

			assertAll(
					() -> assertEquals(List.of(LmdbPlanCacheRevalidation.DROPPED_FOR_SLACK, "within-budget"),
							duringFlight, "while the flight plans, its reservation holds the colder log's slack"),
					() -> assertEquals(2, cache.entryCount()),
					() -> assertNotNull(variant(cache, 1).readLogBasis().log(), "the new family keeps its log"),
					() -> assertEquals(Map.of(LmdbPlanCacheRevalidation.DROPPED_FOR_SLACK, 1L),
							cache.decisionCacheForTest().statistics().revalidation().logsDropped()),
					() -> assertEquals(LmdbPlanCacheRevalidationTest.recomputedCharges(cache.decisionCacheForTest()),
							cache.retainedBytes()));
		} finally {
			cache.close();
		}
	}

	@Test
	void aProvenRepeatIsAdmittedAndEvictsAsWithTheSwitchOffWhileALogFillsTheSlack() throws Exception {
		Sizes sizes = sizes(MEDIUM_LOG_READS);
		assertTrue(sizes.reservation() <= sizes.core() + sizes.log() && sizes.log() + 8L < sizes.reservation(),
				"COVERAGE_PREREQUISITE: a flight needs the room of a family and its log, and more than a log: "
						+ sizes);
		// One family and its log fit exactly: a second key's first flight has no free room, and its proven repeat
		// fits only with no family retained, counted without the log.
		long budget = LmdbPlanDecisionCache.doorkeeperBytes(FAMILIES) + sizes.core() + sizes.log() + 8L;
		Map<Boolean, List<Object>> runs = new LinkedHashMap<>();
		for (boolean validation : new boolean[] { false, true }) {
			System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, Boolean.toString(validation));
			LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILIES, 1, budget);
			try {
				List<Object> outcomes = new ArrayList<>();
				outcomes.add(request(cache, 0, MEDIUM_LOG_READS));
				outcomes.add(request(cache, 1, MEDIUM_LOG_READS));
				outcomes.add(request(cache, 1, MEDIUM_LOG_READS));
				outcomes.add(request(cache, 1, MEDIUM_LOG_READS));
				LmdbPlanDecisionCache.Statistics statistics = cache.decisionCacheForTest().statistics();
				outcomes.add("families=" + statistics.families());
				outcomes.add("evictions=" + statistics.evictions());
				outcomes.add("publications=" + statistics.publications());
				assertEquals(LmdbPlanCacheRevalidationTest.recomputedCharges(cache.decisionCacheForTest()),
						cache.retainedBytes());
				if (validation) {
					assertNotNull(variant(cache, 1), "COVERAGE_PREREQUISITE: the proven repeat was published");
					assertEquals(1L, statistics.revalidation().logsDropped().get(LmdbPlanCacheRevalidation.SHED),
							"the evicted family shed its log first: " + statistics.revalidation().logsDropped());
				}
				runs.put(validation, outcomes);
			} finally {
				cache.close();
			}
		}
		assertEquals(List.of(false, false, false, true, "families=1", "evictions=1", "publications=2"), runs.get(false),
				"COVERAGE_PREREQUISITE: with the switch off the proven repeat evicts the first family");
		assertEquals(runs.get(false), runs.get(true), "every request's outcome and the cache's decisions");
	}

	@Test
	void aFamilyEvictedForRoomShedsItsLogFirst() throws Exception {
		Sizes sizes = sizes();
		// Two families without logs fit, with plenty of slack for logs and reservations.
		long budget = LmdbPlanDecisionCache.doorkeeperBytes(FAMILIES) + 2L * sizes.core() + sizes.core() / 2L
				+ 4L * sizes.log();
		System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, "true");
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILIES, 1, budget);
		try {
			request(cache, 0);
			request(cache, 1);
			// A proven repeat of a third key evicts the least recently used family.
			request(cache, 2);
			request(cache, 2);

			LmdbPlanCacheRevalidation.Snapshot counters = cache.decisionCacheForTest().statistics().revalidation();
			assertAll(
					() -> assertTrue(cache.decisionCacheForTest().statistics().evictions() > 0L,
							"COVERAGE_PREREQUISITE: a family was evicted"),
					() -> assertTrue(counters.logsDropped().getOrDefault(LmdbPlanCacheRevalidation.SHED, 0L) >= 1L,
							"the evicted family's first shed tier is its log: " + counters.logsDropped()),
					() -> assertEquals(LmdbPlanCacheRevalidationTest.recomputedCharges(cache.decisionCacheForTest()),
							cache.retainedBytes()));
		} finally {
			cache.close();
		}
	}

	// ---------------------------------------------------------------- fixtures

	record Sizes(long core, long log, long reservation) {
	}

	record Run(long families, long hits, long publications, long evictions, List<Boolean> outcomes,
			boolean recomputationsMatched, long droppedLogs) {
	}

	/**
	 * One family's bytes without its log, its log's charge, and its flight's reservation, measured on an unconstrained
	 * cache.
	 */
	private Sizes sizes(int reads) throws Exception {
		System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, "true");
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILIES, 1, 1L << 30);
		try {
			long[] reserved = new long[1];
			request(cache, 0, reads, () -> reserved[0] = cache.decisionCacheForTest().reservedBytesForTest());
			LmdbPlanDecisionCache.FamilyVersion family = cache.decisionCacheForTest()
					.residentFamiliesForTest()
					.values()
					.iterator()
					.next();
			LmdbPlanCacheRevalidation.Basis basis = family.dispatcher().variants().get(0).readLogBasis();
			assertTrue(basis.chargedBytes() > 0L, "COVERAGE_PREREQUISITE: the log is charged");
			assertTrue(reserved[0] > 0L, "COVERAGE_PREREQUISITE: the flight holds a reservation");
			assertEquals(family.retainedBytes() + basis.chargedBytes(), cache.retainedBytes());
			return new Sizes(family.retainedBytes(), basis.chargedBytes(), reserved[0]);
		} finally {
			cache.close();
		}
	}

	private Sizes sizes() throws Exception {
		return sizes(1);
	}

	/** Ten keys, each requested twice in a rotation that keeps evicting. */
	private Run run(boolean validation, long budget) throws Exception {
		System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, Boolean.toString(validation));
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(FAMILIES, 1, budget);
		try {
			List<Boolean> outcomes = new ArrayList<>();
			boolean matched = true;
			for (int round = 0; round < 3; round++) {
				for (int key = 0; key < 6; key++) {
					outcomes.add(request(cache, key));
					outcomes.add(request(cache, key));
					matched &= LmdbPlanCacheRevalidationTest.recomputedCharges(cache.decisionCacheForTest()) == cache
							.retainedBytes();
					matched &= cache.retainedBytes() <= budget;
				}
			}
			LmdbPlanDecisionCache.Statistics statistics = cache.decisionCacheForTest().statistics();
			long dropped = statistics.revalidation().logsDropped().values().stream().mapToLong(Long::longValue).sum();
			return new Run(statistics.families(), statistics.hits(), statistics.publications(), statistics.evictions(),
					outcomes, matched, dropped);
		} finally {
			cache.close();
		}
	}

	private boolean request(LmdbPipelinePlanCache cache, int key) throws Exception {
		return request(cache, key, 1);
	}

	private boolean request(LmdbPipelinePlanCache cache, int key, int reads) throws Exception {
		return request(cache, key, reads, () -> {
		});
	}

	/**
	 * One request of key {@code key}; its planning reads {@code reads} learned keys of its own and runs {@code during}.
	 * Returns whether it was a hit.
	 */
	private boolean request(LmdbPipelinePlanCache cache, int key, int reads, Runnable during) throws Exception {
		if (stats == null) {
			stats = LmdbPlanCacheRevalidationTest.feedback(directory);
		}
		if (reads > 1) {
			// A log whose size the test sets: keys with exact evidence keep their objects in both encodings (a compact
			// log keeps only a digest for a read that found nothing).
			for (int read = 0; read < reads; read++) {
				teachOnce("slack-" + key + "-" + read);
			}
		}
		LmdbPipelinePlanCache.Context context = LmdbPlanCacheRevalidationTest.learned(17L, 3L);
		QueryRoot source = LmdbPlanCacheRevalidationTest.query("_anon_s" + requests++, "urn:slack:" + key);
		return cache.getOrComputePlan(source, context, context::revision, () -> {
			for (int read = 0; read < reads; read++) {
				LmdbPlanCacheRevalidationTest.logicalRead(stats,
						LmdbPlanCacheRevalidationTest.logical("slack-" + key + "-" + read));
			}
			during.run();
			source.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
			source.setStringMetricPlanned("optimizer.cascadesCostComparisonCompleteness", "UNAVAILABLE_COST");
			return new LmdbPipelinePlanCache.PlanComputation(source,
					LmdbPlanCacheRevalidationTest.replayOnlySummary(), null);
		}, () -> Long.MIN_VALUE, null).cacheHit();
	}

	private static LmdbPlanDecisionCache.PlanVariant variant(LmdbPipelinePlanCache cache, int key) {
		for (LmdbPlanDecisionCache.FamilyVersion family : cache.decisionCacheForTest()
				.residentFamiliesForTest()
				.values()) {
			for (LmdbPlanDecisionCache.PlanVariant variant : family.dispatcher().variants()) {
				TupleExpr plan = variant.champion().materialize();
				StatementPattern pattern = (StatementPattern) ((Projection) ((QueryRoot) plan).getArg()).getArg();
				if (("urn:slack:" + key).equals(pattern.getPredicateVar().getValue().stringValue())) {
					return variant;
				}
			}
		}
		throw new AssertionError("no resident variant of key " + key);
	}

	@Test
	void aRestampRacingALogDropIsRefusedAndTakesTodaysPath() {
		LmdbPlanCacheRevalidationTest outer = new LmdbPlanCacheRevalidationTest();
		try (LmdbPlanCacheRevalidationTest.Harness harness = outer.new Harness()) {
			harness.publish(LmdbPlanCacheRevalidationTest.learned(17L, 3L), true);
			LmdbPlanCacheRevalidationTest.StubValidator validator = new LmdbPlanCacheRevalidationTest.StubValidator(
					LmdbPlanningReadLog.Verdict.IDENTICAL);
			// While the request replays, the slack takes the variant's log.
			validator.during = () -> harness.decisions().dropReadLogsForTest();

			LmdbPipelinePlanCache.Result result = harness.lookup(LmdbPlanCacheRevalidationTest.learned(17L, 30L), true,
					validator);

			String reason = result.plan().getStringMetricPlanned("optimizer.planCacheRefreshReason");
			assertAll(
					() -> assertEquals(1, validator.calls.get(), "COVERAGE_PREREQUISITE: the variant was replayed"),
					() -> assertFalse(reason != null && reason.startsWith("revalidated"),
							"a log dropped during the replay is not served as revalidated: " + reason),
					() -> assertEquals(0L, harness.revalidation().restamps()),
					() -> assertEquals(1L, harness.revalidation().restampCasLost()),
					() -> assertEquals("USE_AND_REFRESH",
							result.plan().getStringMetricPlanned("optimizer.planCacheLookupOutcome"),
							"today's path: a stale serve with refresh"),
					() -> assertEquals(LmdbPlanCacheRevalidationTest.recomputedCharges(harness.decisions()),
							harness.cache.retainedBytes()));
		}
	}
}
